if isinstance(data, dict):
    for v in data.values():
        if isinstance(v, list):
            data = v
            break

# preserve first-seen key order; include any keys that appear anywhere
fields = []
for rec in data:
    for k in rec.keys():
        if k not in fields:
            fields.append(k)

def flat(v):
    if isinstance(v, (dict, list)):
        return json.dumps(v, ensure_ascii=False)
    return '' if v is None else v

dst = os.path.join(os.path.dirname(src), 'shipments.csv')
with open(dst, 'w', newline='') as f:
    w = csv.writer(f)
    w.writerow(fields)
    for rec in data:
        w.writerow([flat(rec.get(k, '')) for k in fields])

print('WROTE', dst, 'rows=', len(data), 'cols=', fields)
EOF
